%dw 2.0
output application/json skipNullOn="everywhere"

fun isoToUnix(date) =
    if (date == null)
        null
    else
        (date as DateTime) as Number

---
{
    (id: payload.eventId)
        if (payload.eventId?),

    (partner_user_id: payload.partnerUserId)
        if (payload.partnerUserId?),

    (timestamp: isoToUnix(payload.occurredAt))
        if (payload.occurredAt?),

    (event_type: payload.eventType)
        if (payload.eventType?),

    (event_data: {

        (address: {
            (country: payload.eventData.address.country)
                if (payload.eventData.address.country?)
        })
            if (payload.eventData.address?),

        (email: payload.eventData.email)
            if (payload.eventData.email?),

        (phone_number: payload.eventData.phoneNumber)
            if (payload.eventData.phoneNumber?),

        (name: payload.eventData.name)
            if (payload.eventData.name?),

        (products:
            payload.eventData.products map (product) -> {
                (code: product.code) if (product.code?),
                (name: product.name) if (product.name?),
                (starts: isoToUnix(product.starts)) if (product.starts?),
                (renews: isoToUnix(product.renews)) if (product.renews?),
                (expires: isoToUnix(product.expires)) if (product.expires?),
                (sub_id: product.subscriptionId) if (product.subscriptionId?),
                (trx_id: product.transactionId) if (product.transactionId?),
                (status: product.status) if (product.status?),
                (reason: product.reason) if (product.reason?)
            }
        )
            if (payload.eventData.products?),

        (products_terminated:
            payload.eventData.productsTerminated map (product) -> {
                (code: product.code) if (product.code?),
                (sub_id: product.subscriptionId) if (product.subscriptionId?)
            }
        )
            if (payload.eventData.productsTerminated?),

        (products_added:
            payload.eventData.productsAdded map (product) -> {
                (code: product.code) if (product.code?),
                (sub_id: product.subscriptionId) if (product.subscriptionId?),
                (starts: isoToUnix(product.starts)) if (product.starts?),
                (renews: isoToUnix(product.renews)) if (product.renews?),
                (trx_id: product.transactionId) if (product.transactionId?)
            }
        )
            if (payload.eventData.productsAdded?),

        (effective_date: isoToUnix(payload.eventData.effectiveDate))
            if (payload.eventData.effectiveDate?),

        (reason: payload.eventData.reason)
            if (payload.eventData.reason?),

        (details: payload.eventData.details)
            if (payload.eventData.details?)
    })
        if (payload.eventData?)
}

