%dw 2.0
output application/json

fun unixToIso(timestamp) =
    if (timestamp == null)
        null
    else
        (timestamp as DateTime) as String {
            format: "yyyy-MM-dd'T'HH:mm:ss'Z'"
        }

---
{
    code: (payload.Code default 200) as String,
    message: "Subscriptions retrieved successfully",
    data: {
        products: (payload.Result.products default []) map (product) -> {
            code: product.code default "",
            name: product.name default "",
            starts: unixToIso(product.starts),
            expires: unixToIso(product.expires),
            status: product.status default "",
            subscriptionId: product.sub_id default "",
            transactionId: product.trx_id default ""
        }
    }
}

%dw 2.0 output application/json
var product = payload.Result.products[0]
--- { partner_user_id: attributes.uriParams.providerId, code: product.code, sub_id: product.sub_id, starts: product.starts }

