    (event_type: payload.eventType)
        if (payload.eventType?),

    (user_id: payload.userId)
        if (payload.userId?),

    (partner_user_id: payload.partnerUserId)
        if (payload.partnerUserId?),

    (timestamp: isoToUnix(payload.occurredAt))
        if (payload.occurredAt?),

    (event_data: {

        (product: {
            (code: payload.eventData.product.code)
                if (payload.eventData.product.code?),

            (sub_id: payload.eventData.product.subscriptionId)
                if (payload.eventData.product.subscriptionId?),

            (starts: isoToUnix(payload.eventData.product.starts))
                if (payload.eventData.product.starts?),

            (expires: isoToUnix(payload.eventData.product.expires))
                if (payload.eventData.product.expires?),

            (reason: payload.eventData.product.reason)
                if (payload.eventData.product.reason?)
        })
            if (payload.eventData.product?),

        (address: {
            (country: payload.eventData.address.country)
                if (payload.eventData.address.country?)
        })
            if (payload.eventData.address?),

        (email: payload.eventData.email)
            if (payload.eventData.email?),

        (phone_number: payload.eventData.phoneNumber)
            if (payload.eventData.phoneNumber?),

        (name: payload.eventData.name)
            if (payload.eventData.name?),

        (products:
            payload.eventData.products map (product) -> {
                (code: product.code)
                    if (product.code?),

                (sub_id: product.subscriptionId)
                    if (product.subscriptionId?),

                (status: product.status)
                    if (product.status?),

                (starts: isoToUnix(product.starts))
