%dw 2.0
output application/json skipNullOn="everywhere"

var notification = payload

var subId =
    notification.event_data.product.sub_id
        default notification.event_data.products[0].sub_id
        default notification.event_data.products_added[0].sub_id
        default notification.event_data.products_terminated[0].sub_id
        default null

var code =
    notification.event_data.product.code
        default notification.event_data.products[0].code
        default notification.event_data.products_added[0].code
        default notification.event_data.products_terminated[0].code
        default null

---
{
  query: {
    update: "MDM_TRAZABILIDAD_EVENTOS_THIRDPARTY",
    updates: [
      {
        q: {
          "solicitudEvento.partner_user_id": notification.partner_user_id,
          (
            "solicitudEvento.event_data.products": {
              "$elemMatch": {
                (sub_id: subId) if (subId != null),
                (code: code) if (code != null)
              }
            }
          ) if (subId != null or code != null)
        },
        u: {
          "$set": {
            notificacionEvento: notification,
            estado:
              if (notification.event_type == "error_notification")
                "FALLIDO"
              else
                "EXITOSO",
            fechaActualizacion:
              now() as String {
                format: "yyyy-MM-dd'T'HH:mm:ssXXX"
              }
          }
        },
        multi: false,
        upsert: false
      }
    ]
  }
}
